import 'package:flutter/material.dart';
import 'package:go_router/go_router.dart';
import 'theme/app_theme.dart';
import '../features/home/presentation/home_page.dart';

class AppShell extends StatefulWidget { const AppShell({super.key,required this.initialIndex}); final int initialIndex; @override State<AppShell> createState()=>_AppShellState(); }
class _AppShellState extends State<AppShell>{late int index;static const labels=['Home','Friends','Activity','Profile','Worker House'];static const icons=[Icons.home_rounded,Icons.people_alt_outlined,Icons.notifications_none_rounded,Icons.person_outline_rounded,Icons.work_outline_rounded];@override void initState(){super.initState();index=widget.initialIndex;}@override Widget build(BuildContext context){final page=index==0?const HomePage():Center(child:Text(labels[index],style:Theme.of(context).textTheme.headlineSmall));return Scaffold(body:SafeArea(bottom:false,child:page),bottomNavigationBar:SafeArea(minimum:const EdgeInsets.fromLTRB(9,0,9,8),child:Container(height:62,padding:const EdgeInsets.all(5),decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(21),border:Border.all(color:AppTheme.border),boxShadow:const[BoxShadow(blurRadius:28,offset:Offset(0,12),color:Color(0x290F172A))]),child:Row(children:[for(var i=0;i<labels.length;i++)Expanded(child:_Destination(icon:icons[i],label:labels[i],selected:index==i,onTap:(){setState(()=>index=i);context.go(['/home','/friends','/activity','/profile','/worker-house'][i]);}))]))));}}
class _Destination extends StatelessWidget{const _Destination({required this.icon,required this.label,required this.selected,required this.onTap});final IconData icon;final String label;final bool selected;final VoidCallback onTap;@override Widget build(BuildContext context)=>Semantics(button:true,selected:selected,label:label,child:InkWell(borderRadius:BorderRadius.circular(16),onTap:onTap,child:AnimatedContainer(duration:const Duration(milliseconds:180),margin:const EdgeInsets.symmetric(horizontal:2),padding:const EdgeInsets.symmetric(vertical:5),decoration:BoxDecoration(gradient:selected?AppTheme.brandGradient:null,borderRadius:BorderRadius.circular(16)),child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[Icon(icon,size:18,color:selected?Colors.white:AppTheme.textSecondary),const SizedBox(height:2),Text(label,maxLines:1,overflow:TextOverflow.ellipsis,style:TextStyle(fontSize:8,fontWeight:FontWeight.w900,color:selected?Colors.white:AppTheme.textSecondary))]))));}
